  return await productsCollection.find({ category: category });
}
// Vulnerability: $where with string interpolation allows arbitrary
// JavaScript injection into MongoDB's query engine, a
// MongoDB-specific equivalent of traditional SQL injection.

sections.content:
CSRF PROTECTION - using a genuinely unpredictable, per-session
CSRF TOKEN that a malicious, third-party site genuinely cannot know
or guess, required on every state-changing request:

app.post('/transfer-funds', requireAuth, csrfProtection, async (req, res, next) => {
  // csrfProtection middleware verifies the request includes a valid
  // CSRF token matching this user's own session - a malicious site
  // tricking the victim's browser into submitting this request has
  // NO WAY to know or include this specific, unpredictable token
  // ...
});

AUTHENTICATION VERSUS AUTHORIZATION - directly naming Module 9's
existing, already-correct two-step pattern with its precise vocabulary:

app.patch('/projects/:id', requireAuth, async (req, res, next) => {
  // STEP 1 - AUTHENTICATION (requireAuth middleware): WHO is making
  // this request? Confirmed via a genuinely valid JWT/session.

  const project = await projectRepository.findById(req.params.id);

  // STEP 2 - AUTHORIZATION: is THIS specific, authenticated user
  // actually ALLOWED to modify THIS specific project?
  if (project.ownerId !== req.userId) {
    return res.status(403).json({ success: false, error: 'Forbidden' });
    // 403, NOT 401 - the user IS genuinely authenticated; they are
    // simply not AUTHORIZED for this specific resource
  }
  // ... proceed with the update
});

