// VICTIM is genuinely, currently logged into 'mybank.com' in one
// browser tab. They then visit a malicious site, 'evil.com', in
// ANOTHER tab, which contains:

// <form action="https://mybank.com/transfer-funds" method="POST">
//   <input type="hidden" name="amount" value="5000">
//   <input type="hidden" name="toAccount" value="attacker-account">
// </form>
// <script>document.forms[0].submit()</script> // auto-submits
// immediately, with NO interaction from the victim at all

// UNPROTECTED endpoint (no CSRF check):
app.post('/transfer-funds', requireAuth, async (req, res) => {
  // requireAuth checks for a valid session COOKIE - and the
  // victim's browser AUTOMATICALLY attaches their genuine,
  // currently-valid mybank.com cookie to this request, even though
  // it originated from evil.com's malicious form - the transfer
  // GENUINELY succeeds, using the victim's own, real authentication
  await processTransfer(req.userId, req.body.amount, req.body.toAccount);
  res.json({ success: true });
});

// PROTECTED endpoint, with CSRF token verification:
app.post('/transfer-funds', requireAuth, csrfProtection, async (req, res) => {
  // evil.com's malicious form has NO WAY to know or include
  // mybank.com's own, genuinely unpredictable CSRF token (which is
  // NOT stored in a cookie alone, specifically so it cannot be
  // automatically, silently attached the same way a cookie is) -
  // csrfProtection middleware correctly REJECTS this exact request,
  // even though the victim's genuine session cookie was present
  await processTransfer(req.userId, req.body.amount, req.body.toAccount);
  res.json({ success: true });
});

