codingChallenge.solutionExample:
async function rateLimitMiddleware(req: Request, res: Response, next: NextFunction) {
  const identifier = req.userId ?? req.ip;
  const key = `ratelimit:general:${identifier}`;
  const count = await redisClient.incr(key);

  if (count === 1) await redisClient.expire(key, 60);

  if (count > 100) {
    return res.status(429).json({ success: false, error: 'Too many requests' });
  }
  next();
}

function createRateLimiter(windowSeconds: number, maxAttempts: number) {
  return async function (req: Request, res: Response, next: NextFunction) {
    const identifier = req.userId ?? req.ip;
    const key = `ratelimit:custom:${identifier}:${req.path}`;
    const count = await redisClient.incr(key);

    if (count === 1) await redisClient.expire(key, windowSeconds);

    if (count > maxAttempts) {
      return res.status(429).json({ success: false, error: 'Too many requests' });
    }
    next();
  };
}

app.use(rateLimitMiddleware); // general limiter, applied broadly

const passwordResetLimiter = createRateLimiter(900, 3); // 15 min, 3 attempts
app.post('/password-reset', passwordResetLimiter, async (req, res, next) => { /* ... */ });

